using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using BanhangcodeX.Data;using BanhangcodeX.Models;
namespace BanhangcodeX.Controllers;
[ApiController,Route("api/auth")]public class AuthController(AppDbContext db,IPasswordHasher<AppUser> hasher):ControllerBase{public record Login(string UserName,string Password);public record Change(string CurrentPassword,string NewPassword);[HttpGet("me"),Authorize]public IActionResult Me()=>Ok(new{user=User.Identity?.Name});[HttpPost("login")]public async Task<IActionResult> LoginUser(Login x){var u=await db.Users.SingleOrDefaultAsync(a=>a.UserName==x.UserName);if(u==null||hasher.VerifyHashedPassword(u,u.PasswordHash,x.Password)==PasswordVerificationResult.Failed)return Unauthorized(new{message="Tài khoản hoặc mật khẩu không đúng."});await HttpContext.SignInAsync("Cookies",new System.Security.Claims.ClaimsPrincipal(new System.Security.Claims.ClaimsIdentity([new System.Security.Claims.Claim(System.Security.Claims.ClaimTypes.Name,u.UserName)],"Cookies")));return Ok(new{user=u.UserName});}[HttpPost("logout"),Authorize]public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync("Cookies");return Ok();}[HttpPost("change-password"),Authorize]public async Task<IActionResult> ChangePassword(Change x){var u=await db.Users.SingleOrDefaultAsync(a=>a.UserName==User.Identity!.Name);if(u==null||hasher.VerifyHashedPassword(u,u.PasswordHash,x.CurrentPassword)==PasswordVerificationResult.Failed)return BadRequest(new{message="Mật khẩu hiện tại không đúng."});if(x.NewPassword.Length<10)return BadRequest(new{message="Mật khẩu cần ít nhất 10 ký tự."});u.PasswordHash=hasher.HashPassword(u,x.NewPassword);await db.SaveChangesAsync();return Ok(new{message="Đã đổi mật khẩu."});}}

